// Main JavaScript for Zahara Schaefer Personal Website

document.addEventListener('DOMContentLoaded', function() {
    // Initialize navigation
    initNavigation();
    
    // Initialize smooth scrolling
    initSmoothScrolling();
    
    // Initialize animations
    initAnimations();
    
    // Initialize PostHog tracking
    initPostHogTracking();
});

function initNavigation() {
    const navbar = document.querySelector('.navbar');
    const navLinks = document.querySelectorAll('.nav-link');
    
    // Add active class to current page
    const currentPath = window.location.pathname;
    navLinks.forEach(link => {
        if (link.getAttribute('href') === currentPath) {
            link.classList.add('active');
        }
    });
    
    // Let Bootstrap handle the collapse - don't interfere with it
}

function initSmoothScrolling() {
    const links = document.querySelectorAll('a[href^="#"]');
    
    links.forEach(link => {
        link.addEventListener('click', function(e) {
            const href = this.getAttribute('href');
            if (href === '#') return;
            
            const target = document.querySelector(href);
            if (target) {
                e.preventDefault();
                target.scrollIntoView({
                    behavior: 'smooth',
                    block: 'start'
                });
            }
        });
    });
}

function initAnimations() {
    // Simple fade-in animation for elements
    const animatedElements = document.querySelectorAll('.fade-in');
    
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.style.opacity = '1';
                entry.target.style.transform = 'translateY(0)';
            }
        });
    });
    
    animatedElements.forEach(element => {
        element.style.opacity = '0';
        element.style.transform = 'translateY(20px)';
        element.style.transition = 'opacity 0.6s ease, transform 0.6s ease';
        observer.observe(element);
    });
}

function initPostHogTracking() {
    // Use window.posthog and helper functions for consistent tracking
    if (window.posthog && typeof window.posthog.capture === 'function') {
        // Track page view
        window.trackEvent('$pageview', {
            page_type: 'website'
        });
        
        // Track button clicks
        const buttons = document.querySelectorAll('button, .btn');
        buttons.forEach(button => {
            button.addEventListener('click', function() {
                window.trackEvent('button_clicked', {
                    button_text: this.textContent.trim(),
                    button_class: this.className,
                    button_id: this.id || null,
                    button_type: this.type || null
                });
            });
        });
        
        // Track link clicks
        const links = document.querySelectorAll('a[href]');
        links.forEach(link => {
            link.addEventListener('click', function() {
                window.trackEvent('link_clicked', {
                    link_text: this.textContent.trim(),
                    link_url: this.href,
                    link_target: this.target || '_self',
                    is_external: this.hostname !== window.location.hostname
                });
            });
        });
        
        // Track scroll depth
        let maxScroll = 0;
        window.addEventListener('scroll', function() {
            const scrollPercent = Math.round((window.scrollY / (document.body.scrollHeight - window.innerHeight)) * 100);
            
            if (scrollPercent > maxScroll) {
                maxScroll = scrollPercent;
                
                // Track milestone scroll depths
                if (maxScroll >= 25 && maxScroll < 50) {
                    window.trackEvent('scroll_depth_25', { scroll_percent: 25 });
                } else if (maxScroll >= 50 && maxScroll < 75) {
                    window.trackEvent('scroll_depth_50', { scroll_percent: 50 });
                } else if (maxScroll >= 75 && maxScroll < 90) {
                    window.trackEvent('scroll_depth_75', { scroll_percent: 75 });
                } else if (maxScroll >= 90) {
                    window.trackEvent('scroll_depth_90', { scroll_percent: 90 });
                }
            }
        });
    }
}

// Utility functions
function showNotification(message, type = 'info') {
    const notification = document.createElement('div');
    notification.className = `alert alert-${type} alert-dismissible fade show`;
    notification.style.position = 'fixed';
    notification.style.top = '20px';
    notification.style.right = '20px';
    notification.style.zIndex = '9999';
    notification.innerHTML = `
        ${message}
        <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
    `;
    
    document.body.appendChild(notification);
    
    // Auto-remove after 5 seconds
    setTimeout(() => {
        notification.remove();
    }, 5000);
}

// Export functions for global use
window.showNotification = showNotification;
